50	func wantHash(seq int64, account, operation, resource, result, occurredAt, prevHash string) string {
51		payload := fmt.Sprintf(`[%d,"%s","%s","%s","%s","%s","%s"]`, seq, account, operation, resource, result, occurredAt, prevHash)
52		sum := sha256.Sum256([]byte(payload))
53		return hex.EncodeToString(sum[:])
54	}
