163	func TestPostEventExplicitSeq(t *testing.T) {
164		router := NewRouter(openTestStore(t))
165	
166		// Explicit seq equal to the next sequence number is accepted.
167		body := `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","seq":1}`
168		if recorder := postEventBody(t, router, body); recorder.Code != http.StatusCreated {
169			t.Fatalf("explicit next seq: status = %d (%s)", recorder.Code, recorder.Body.String())
170		}
171	
172		// An existing seq conflicts.
173		if recorder := postEventBody(t, router, body); recorder.Code != http.StatusConflict {
174			t.Fatalf("existing seq: status = %d, want 409 (%s)", recorder.Code, recorder.Body.String())
175		} else if event := decodeEvent(t, recorder); event["error"].(map[string]any)["code"] != "audit_seq_conflict" {
176			t.Fatalf("existing seq: code = %v", event)
177		}
178	
179		// A seq past the next one is rejected as invalid input.
180		gap := `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z","seq":5}`
181		recorder := postEventBody(t, router, gap)
182		if recorder.Code != http.StatusBadRequest {
183			t.Fatalf("gap seq: status = %d, want 400 (%s)", recorder.Code, recorder.Body.String())
184		}
185		if event := decodeEvent(t, recorder); event["error"].(map[string]any)["code"] != "invalid_audit_input" {
186			t.Fatalf("gap seq: body = %v", event)
187		}
188	
189		// Failed appends consume no sequence number: the next append is seq 2.
190		recorder = postEventBody(t, router, validEventBody())
191		if recorder.Code != http.StatusCreated {
192			t.Fatalf("status = %d (%s)", recorder.Code, recorder.Body.String())
193		}
194		if event := decodeEvent(t, recorder); event["seq"] != float64(2) {
195			t.Fatalf("seq = %v, want 2 after failed appends", event["seq"])
196		}
197	}
