308	// wantInvalidTime posts one event body and asserts the invalid_audit_input
309	// rejection shape: 400, only a top-level error object, and no internals.
310	func wantInvalidTime(t *testing.T, router http.Handler, body string) {
311		t.Helper()
312		recorder := postEventBody(t, router, body)
313		if recorder.Code != http.StatusBadRequest {
314			t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusBadRequest, recorder.Body.String())
315		}
316		decoded := decodeEvent(t, recorder)
317		if len(decoded) != 1 {
318			t.Fatalf("response keys = %v, want only the error object", decoded)
319		}
320		errObj, ok := decoded["error"].(map[string]any)
321		if !ok {
322			t.Fatalf("error = %v, want an object", decoded["error"])
323		}
324		if errObj["code"] != "invalid_audit_input" {
325			t.Fatalf("code = %v, want invalid_audit_input", errObj["code"])
326		}
327		if message, ok := errObj["message"].(string); !ok || message == "" {
328			t.Fatalf("message = %v, want a non-empty string", errObj["message"])
329		}
330		leaks := []string{"sql", "SELECT", "INSERT", "goroutine", ".go", "/", "\\"}
331		for _, leak := range leaks {
332			if strings.Contains(recorder.Body.String(), leak) {
333				t.Fatalf("response leaks internals (%q): %s", leak, recorder.Body.String())
334			}
335		}
336	}
