368	func TestPostEventAcceptsBoundaryUTCYear(t *testing.T) {
369		path := filepath.Join(t.TempDir(), "service.db")
370		st, err := store.Open(path)
371		if err != nil {
372			t.Fatalf("open: %v", err)
373		}
374		defer st.Close()
375		router := NewRouter(st)
376	
377		cases := []struct {
378			occurredAt string
379			wantUTC    string
380		}{
381			// One minute inside the lower bound: UTC lands exactly on 0000-01-01T00:00:00Z.
382			{"0000-01-01T00:01:00+00:01", "0000-01-01T00:00:00Z"},
383			// One minute inside the upper bound: UTC lands exactly on 9999-12-31T23:59:59Z.
384			{"9999-12-31T23:58:59-00:01", "9999-12-31T23:59:59Z"},
385		}
386		prevHash := strings.Repeat("0", 64)
387		for i, tc := range cases {
388			recorder := postEventBody(t, router,
389				fmt.Sprintf(`{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":%q}`, tc.occurredAt))
390			if recorder.Code != http.StatusCreated {
391				t.Fatalf("%s: status = %d (%s)", tc.occurredAt, recorder.Code, recorder.Body.String())
392			}
393			event := decodeEvent(t, recorder)
394			if event["occurred_at"] != tc.wantUTC {
395				t.Fatalf("%s: occurred_at = %v, want %v", tc.occurredAt, event["occurred_at"], tc.wantUTC)
396			}
397			seq := int64(i + 1)
398			if event["seq"] != float64(seq) {
399				t.Fatalf("%s: seq = %v, want %d", tc.occurredAt, event["seq"], seq)
400			}
401			want := wantHash(seq, "a", "o", "r", "ok", tc.wantUTC, prevHash)
402			if event["hash"] != want {
403				t.Fatalf("%s: hash = %v, want %v (normalized time must feed the hash)", tc.occurredAt, event["hash"], want)
404			}
405			prevHash = event["hash"].(string)
406		}
407	
408		// The persisted rows carry the same normalized UTC timestamps.
409		stored := readStoredEvents(t, path)
410		if len(stored) != len(cases) {
411			t.Fatalf("stored %d events, want %d", len(stored), len(cases))
412		}
413		for i, tc := range cases {
414			if stored[i].occurredAt != tc.wantUTC {
415				t.Fatalf("stored occurred_at = %v, want %v", stored[i].occurredAt, tc.wantUTC)
416			}
417		}
418	}
