		for i := start; i < start+width; i++ {
			if head[i] < '0' || head[i] > '9' {
				return 0, false
			}
			v = v*10 + int(head[i]-'0')
		}
		return v, true
	}
	year, ok1 := field(0, 4)
	month, ok2 := field(5, 2)
	day, ok3 := field(8, 2)
	hour, ok4 := field(11, 2)
	minute, ok5 := field(14, 2)
	second, ok6 := field(17, 2)
	if !ok1 || !ok2 || !ok3 || !ok4 || !ok5 || !ok6 {
		return "", false
	}
	if second > 59 {
		// Leap seconds are not accepted.
		return "", false
	}

	rest := value[headLen:]
	fraction := ""
	if strings.HasPrefix(rest, ".") {
		i := 1
		for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
			i++
		}
		if i == 1 {
			return "", false
		}
		fraction = rest[:i]
		rest = rest[i:]
	}

	offsetMinutes := 0
